// Ternary search for the peak of a unimodal function on [lo, hi]
function ternarySearchMax(f, lo, hi) {
  while (hi - lo > 2) {
    const m1 = lo + Math.floor((hi - lo) / 3);
    const m2 = hi - Math.floor((hi - lo) / 3);
    if (f(m1) < f(m2)) lo = m1 + 1;  // peak can't be left of m1
    else hi = m2 - 1;                // peak can't be right of m2
  }
  let best = lo;
  for (let i = lo + 1; i <= hi; i++) if (f(i) > f(best)) best = i;
  return best;
}

// 0-1 BFS using a deque (array with push/shift/unshift as a stand-in)
function zeroOneBFS(n, edges, source) {   // edges[u] = list of [v, weight] with weight in {0, 1}
  const dist = new Array(n).fill(Infinity);
  dist[source] = 0;
  const deque = [source];
  while (deque.length) {
    const u = deque.shift();
    for (const [v, w] of edges[u]) {
      if (dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        if (w === 0) deque.unshift(v);  // 0-weight: process next (front)
        else deque.push(v);              // 1-weight: process later (back)
      }
    }
  }
  return dist;
}

// Extended Euclidean algorithm - returns [gcd, x, y] such that a*x + b*y = gcd
function extendedGCD(a, b) {
  if (b === 0) return [a, 1, 0];
  const [g, x1, y1] = extendedGCD(b, a % b);
  return [g, y1, x1 - Math.floor(a / b) * y1];
}
